"""Local Chromium smoke tests. In-memory document; not a hosted or WCAG audit."""
from pathlib import Path
from datetime import datetime, timezone
import json, hashlib, sys
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
HTML=(ROOT/'dist/puds-pm2-daimac.html').read_text()
results=[]; errors=[]; requests=[]
def check(name, fn):
    try:
        value=fn()
        if value is not True: raise AssertionError(str(value))
        results.append({'name':name,'status':'PASSED'})
    except Exception as exc:
        results.append({'name':name,'status':'FAILED','detail':str(exc)[:1000]})
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader'],timeout=20000)
    context=browser.new_context(viewport={'width':1440,'height':1000},accept_downloads=True)
    page=context.new_page();page.on('pageerror',lambda err:errors.append(str(err)));page.on('request',lambda req:requests.append(req.url))
    page.set_content(HTML,wait_until='load');page.wait_for_timeout(200)
    check('desktop renders four project cards',lambda:page.locator('.project').count()==4)
    check('desktop renders four case narratives',lambda:page.locator('.case').count()==4)
    check('registry renders six inspectable rows',lambda:page.locator('.registry-cell').count()==6)
    check('single accessible primary heading',lambda:page.locator('h1').count()==1 and page.locator('h1').get_attribute('aria-label')=='Meaning in motion.')
    check('all internal href destinations resolve',lambda:page.evaluate("[...document.querySelectorAll('a[href^=\"#\"]')].every(a=>a.hash.length>1&&document.getElementById(a.hash.slice(1)))"))
    check('unique DOM identifiers',lambda:page.evaluate("(()=>{const ids=[...document.querySelectorAll('[id]')].map(n=>n.id);return ids.length===new Set(ids).size})()"))
    check('all aria-labelledby references resolve',lambda:page.evaluate("[...document.querySelectorAll('[aria-labelledby]')].every(n=>n.getAttribute('aria-labelledby').split(/\\s+/).every(id=>document.getElementById(id)))"))
    check('all form controls have associated labels',lambda:page.evaluate("[...document.querySelectorAll('input,select,textarea')].every(n=>n.labels.length>0)"))
    check('desktop has no page horizontal overflow',lambda:page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
    page.locator('[data-filter="Evidence"]').click()
    check('category filter exposes exactly one matching project',lambda:page.locator('.project:visible').count()==1 and page.locator('.project:visible').get_attribute('data-category')=='Evidence')
    check('filter announces updated count',lambda:page.locator('#filter-status').inner_text().startswith('1 of 4'))
    check('only one category is pressed',lambda:page.locator('[data-filter][aria-pressed="true"]').count()==1)
    page.locator('[data-filter="All"]').click()
    page.locator('#case-rail').focus();page.keyboard.press('End');page.wait_for_timeout(400)
    check('End key selects and focuses last case',lambda:page.evaluate("document.activeElement.id==='case-3'"))
    check('last case disables next button',lambda:page.locator('#next-case').is_disabled())
    page.keyboard.press('Home');page.wait_for_timeout(400)
    check('Home key selects first case',lambda:page.evaluate("document.activeElement.id==='case-0'"))
    page.locator('#list-view').click()
    check('list mode removes horizontal dependency',lambda:page.locator('#case-rail').evaluate("n=>getComputedStyle(n).display==='grid'&&getComputedStyle(n).overflowX==='visible'"))
    page.locator('#list-view').click()
    page.locator('[data-service="Evidence architecture"]').click()
    check('service selection updates intake destination',lambda:page.locator('#brief-service').input_value()=='Evidence architecture')
    check('service description updates coherently',lambda:'traceable' in page.locator('#service-copy').inner_text())
    page.locator('#theme').click()
    check('PM2 theme preserves semantic aliases',lambda:page.evaluate("document.documentElement.dataset.theme==='pm2'&&getComputedStyle(document.documentElement).getPropertyValue('--sys-accent').trim()==='#00FF66'"))
    page.keyboard.press('Tab');page.locator('#theme').focus()
    check('keyboard focus has visible outline',lambda:page.locator('#theme').evaluate("n=>parseFloat(getComputedStyle(n).outlineWidth)>=3"))
    page.screenshot(path=str(ROOT/'evidence/desktop-pm2.png'),full_page=True)
    page.locator('#theme').click();page.evaluate('window.scrollTo(0,0)');page.wait_for_timeout(150)
    before=page.locator('.char-slot').evaluate_all("ns=>ns.map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})")
    box=page.locator('.char-slot').nth(2).bounding_box();page.mouse.move(box['x']+box['width']/2,box['y']+box['height']/2);page.wait_for_timeout(250)
    check('fine pointer applies kinetic transform',lambda:page.locator('.char').evaluate_all("ns=>ns.some(n=>getComputedStyle(n).transform!=='none')"))
    after=page.locator('.char-slot').evaluate_all("ns=>ns.map(n=>{const r=n.getBoundingClientRect();return [r.x,r.y,r.width,r.height]})")
    check('cursor transforms leave layout-slot bounds unchanged',lambda:before==after)
    page.emulate_media(reduced_motion='reduce');page.wait_for_timeout(100)
    check('runtime reduced-motion change disables toggle',lambda:page.locator('#motion').is_disabled())
    check('reduced motion removes every character transform',lambda:page.locator('.char').evaluate_all("ns=>ns.every(n=>getComputedStyle(n).transform==='none')"))
    page.emulate_media(reduced_motion='no-preference');page.wait_for_timeout(100);page.locator('#motion').uncheck()
    check('explicit motion off resets transforms',lambda:page.locator('.char').evaluate_all("ns=>ns.every(n=>getComputedStyle(n).transform==='none')"))
    page.locator('#grid-toggle').click()
    check('grid toggle exposes noninteractive overlay',lambda:page.locator('#grid-overlay').is_visible() and page.locator('#grid-overlay').evaluate("n=>getComputedStyle(n).pointerEvents==='none'"))
    page.locator('#grid-toggle').click()
    page.locator('#registry > details > summary').click();page.locator('#render-shader').click()
    shader=page.locator('#shader-status').inner_text()
    check('WebGL sample renders or exposes an explicit static fallback',lambda:shader.startswith('LOCAL COMPILE + LINK + DRAW PASSED') or shader.startswith('UNAVAILABLE /'))
    page.locator('#brief-goal').fill('Connect design tokens and validate accessible interaction.')
    with page.expect_download(timeout=5000) as download_info: page.locator('#brief-form button').click()
    download=download_info.value;download.save_as(str(ROOT/'evidence/test-brief.json'));brief=json.loads((ROOT/'evidence/test-brief.json').read_text())
    check('CTA produces real local JSON without submission',lambda:brief['submitted'] is False and brief['service']=='Evidence architecture')
    check('release gate remains unauthorized',lambda:'DEPLOYMENT AUTHORIZED: false' in page.locator('#gate-log').inner_text())
    check('no JavaScript exceptions',lambda:len(errors)==0)
    check('no network requests from specimen',lambda:len(requests)==0)
    page.evaluate('window.scrollTo(0,0)');page.screenshot(path=str(ROOT/'evidence/desktop.png'),full_page=True)
    # Frame timing is a local software-renderer observation, not a production smoothness decision.
    timing=page.evaluate("""async()=>{const values=[];let last;await new Promise(resolve=>{function step(t){if(last!==undefined)values.push(t-last);last=t;if(values.length<90)requestAnimationFrame(step);else resolve()}requestAnimationFrame(step)});const s=[...values].sort((a,b)=>a-b);return{count:values.length,p50_ms:s[Math.floor(s.length*.5)],p95_ms:s[Math.floor(s.length*.95)],max_ms:s.at(-1),scope:'idle frame timing only; no device-fleet performance claim'}}""")
    for width in [320,390,768,1024]:
        mobile=browser.new_context(viewport={'width':width,'height':844},is_mobile=width<768,has_touch=width<768,reduced_motion='reduce' if width==320 else 'no-preference')
        mp=mobile.new_page();mp.set_content(HTML,wait_until='load');mp.wait_for_timeout(80)
        check(str(width)+'px has no page horizontal overflow',lambda mp=mp:mp.evaluate('document.documentElement.scrollWidth<=innerWidth'))
        if width<768:
            check(str(width)+'px touch uses static hero',lambda mp=mp:mp.locator('#motion').is_disabled())
            check(str(width)+'px cases remain vertically readable',lambda mp=mp:mp.locator('#case-rail').evaluate("n=>getComputedStyle(n).display==='grid'"))
        if width==390:mp.screenshot(path=str(ROOT/'evidence/mobile.png'),full_page=True)
        mobile.close()
    # Text-only sizing check (not a substitute for every browser's zoom behavior).
    page.add_style_tag(content='html{font-size:32px!important}');page.set_viewport_size({'width':1280,'height':900})
    check('200 percent root text size does not overflow the page',lambda:page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
    fallback=browser.new_context(java_script_enabled=False,viewport={'width':390,'height':844});fp=fallback.new_page();fp.set_content(HTML,wait_until='load')
    check('no-JavaScript hero and fallback explanation remain readable',lambda:fp.locator('h1').is_visible() and 'Scenario index:' in fp.locator('body').inner_text())
    fallback.close()
    report={'executedAt':datetime.now(timezone.utc).isoformat(),'browser':'Chromium '+browser.version,'documentMode':'in-memory standalone; HTTP navigation blocked by environment policy','artifactSha256':hashlib.sha256(HTML.encode()).hexdigest(),'checks':results,'passed':sum(r['status']=='PASSED' for r in results),'failed':sum(r['status']=='FAILED' for r in results),'consoleErrors':errors,'networkRequests':requests,'shader':shader,'shaderCompilation': 'PASSED' if shader.startswith('LOCAL COMPILE') else 'NOT_PERFORMED', 'timing':timing,'limits':['Not a complete WCAG audit','No real iOS/Safari/Firefox test','No hosted deployment test','No authenticated backend integration','No independent verification','No deployment authority']}
    (ROOT/'evidence/browser-report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2));browser.close()
sys.exit(1 if report['failed'] else 0)
